using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ── Configuration ──────────────────────────────────────────────────────
var apiKey  = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? throw new InvalidOperationException("Set the OPENAI_API_KEY environment variable.");
var model   = Environment.GetEnvironmentVariable("OPENAI_MODEL")   ?? "gpt-4o-mini";

// ── Shared state ───────────────────────────────────────────────────────
var notes      = new List<string>();
using var http = new HttpClient();
http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");

// ── Tool definitions ───────────────────────────────────────────────────
var tools = new AITool[]
{
    AIFunctionFactory.Create(SearchWeb),
    AIFunctionFactory.Create(SaveNote),
    AIFunctionFactory.Create(GetNotes),
};

// ── Build AI client with automatic function-invocation middleware ──────
IChatClient client = new ChatClientBuilder(
        new OpenAIClient(apiKey).GetChatClient(model).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

// ── Prompt ──────────────────────────────────────────────────────────────
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your goal is to thoroughly research the topic the
        user provides by following these steps:

        1. Use the search_web tool multiple times with varied queries to gather
           broad and detailed information about the topic.
        2. As you discover key facts, statistics, or insights, use the save_note
           tool to record each important finding.
        3. When you have gathered enough information (at least 5 notes), use the
           get_notes tool to review everything you have collected.
        4. Finally, write a well-structured summary of your research findings,
           organized with clear headings and bullet points.

        Be thorough, use multiple search queries, and cite specifics where possible.
        """),
    new(ChatRole.User, $"Please research the following topic: {topic}"),
};

var options = new ChatOptions
{
    Tools = [.. tools],
    Temperature = 0.3f,
};

// ── Run the agent loop (middleware handles tool calls automatically) ───
Console.WriteLine("Agent is working...\n");
var response = await client.GetResponseAsync(messages, options);
Console.WriteLine("═══ Research Summary ═══\n");
Console.WriteLine(response.Text);
Console.WriteLine($"\n📝 Total notes collected: {notes.Count}");

// ── Tool implementations ───────────────────────────────────────────────

[Description("Search the web for information. Returns relevant snippets about the query.")]
async Task<string> SearchWeb(
    [Description("The search query to look up")] string query)
{
    try
    {
        var encoded = WebUtility.UrlEncode(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
        var json = await http.GetStringAsync(url);
        using var doc = JsonDocument.Parse(json);
        var root = doc.RootElement;
        var sb = new StringBuilder();

        var abs = root.GetProperty("Abstract").GetString();
        var absSource = root.GetProperty("AbstractSource").GetString();
        if (!string.IsNullOrWhiteSpace(abs))
            sb.AppendLine($"[{absSource}] {abs}");

        if (root.TryGetProperty("RelatedTopics", out var topics))
        {
            int count = 0;
            foreach (var t in topics.EnumerateArray())
            {
                if (t.TryGetProperty("Text", out var text) &&
                    !string.IsNullOrWhiteSpace(text.GetString()))
                {
                    sb.AppendLine($"• {text.GetString()}");
                    if (++count >= 8) break;
                }
            }
        }

        var result = sb.ToString();
        if (string.IsNullOrWhiteSpace(result))
            return $"No detailed results for '{query}'. Try different keywords.";

        Console.WriteLine($"  🌐 Searched: {query}");
        return result;
    }
    catch (Exception ex)
    {
        return $"Search error: {ex.Message}";
    }
}

[Description("Save a research note or key finding for later use in the final summary.")]
string SaveNote(
    [Description("The note or finding to save")] string note)
{
    notes.Add(note);
    Console.WriteLine($"  📌 Note #{notes.Count} saved");
    return $"Note saved. You now have {notes.Count} note(s).";
}

[Description("Retrieve all saved research notes to review before writing the summary.")]
string GetNotes()
{
    if (notes.Count == 0)
        return "No notes saved yet.";

    var sb = new StringBuilder();
    for (int i = 0; i < notes.Count; i++)
        sb.AppendLine($"[{i + 1}] {notes[i]}");

    Console.WriteLine($"  📋 Retrieved {notes.Count} notes");
    return sb.ToString();
}

